import{_ as e,c as o,o as s,a2 as t}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"BaseController","description":"","frontmatter":{"sidebarPos":4,"sidebarTitle":"BaseController"},"headers":[],"relativePath":"system-reference/backend/http/controllers/base-controller.md","filePath":"system-reference/backend/http/controllers/base-controller.md","lastUpdated":1778363927000}'),r={name:"system-reference/backend/http/controllers/base-controller.md"},a=t('<h1 id="basecontroller" tabindex="-1">BaseController <a class="header-anchor" href="#basecontroller" aria-label="Permalink to &quot;BaseController&quot;">​</a></h1><p><strong>File</strong>: <code>src/Http/Controllers/BaseController.php</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Http\\Controllers</code><br><strong>Extends</strong>: <code>PanelController</code><br><strong>Traits</strong>: <code>ManageIndexAjax</code>, <code>ManagePrevious</code>, <code>ManageUtilities</code>, <code>ManageSingleton</code>, <code>ManageInertia</code>, <code>ManageTranslations</code></p><p>Standard CRUD controller for the Modularous admin panel. Generated module controllers extend this class and inherit all of the actions below. Override any method in the generated controller to customise behaviour for that module.</p><h2 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h2><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __construct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Application</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $app, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Request</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $request)</span></span></code></pre></div><p>Calls <code>PanelController::__construct()</code> and sets <code>$viewPrefix</code> to <code>{module}::{route}</code> (e.g. <code>blog::posts</code>).</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table><thead><tr><th>Property</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>$viewPrefix</code></td><td><code>string</code></td><td>Blade/Inertia view namespace (e.g. <code>blog::posts</code>)</td></tr><tr><td><code>$titleFormKey</code></td><td><code>string</code></td><td>Model attribute used as title in form headers</td></tr></tbody></table><h2 id="crud-actions" tabindex="-1">CRUD Actions <a class="header-anchor" href="#crud-actions" aria-label="Permalink to &quot;CRUD Actions&quot;">​</a></h2><h3 id="index-parentid-null-view-jsonresponse" tabindex="-1"><code>index($parentId = null): View|JsonResponse</code> <a class="header-anchor" href="#index-parentid-null-view-jsonresponse" aria-label="Permalink to &quot;`index($parentId = null): View|JsonResponse`&quot;">​</a></h3><p>Lists all resources. Returns AJAX-formatted JSON when requested via <code>X-Requested-With: XMLHttpRequest</code>, otherwise renders the index view. Respects scopes, filters, and ordering from <code>PanelController</code>.</p><h3 id="create-parentid-null-jsonresponse-redirectresponse-view" tabindex="-1"><code>create($parentId = null): JsonResponse|RedirectResponse|View</code> <a class="header-anchor" href="#create-parentid-null-jsonresponse-redirectresponse-view" aria-label="Permalink to &quot;`create($parentId = null): JsonResponse|RedirectResponse|View`&quot;">​</a></h3><p>Shows the create form. Returns the form schema, field definitions, and relationship data. Redirects to index if the <code>create</code> index option is disabled.</p><h3 id="store-parentid-null-jsonresponse-redirectresponse" tabindex="-1"><code>store($parentId = null): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#store-parentid-null-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`store($parentId = null): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Validates the request via <code>validateFormRequest()</code> then calls <code>$repository-&gt;create()</code>. On success:</p><ul><li>Logs activity (<code>created</code>).</li><li>Respects <code>cmsSaveType</code> header to redirect to <code>save-close</code> (index) or <code>save-new</code> (create form).</li><li>Returns JSON for Inertia requests.</li></ul><h3 id="show-id-submoduleid-null-redirectresponse-jsonresponse-view" tabindex="-1"><code>show($id, $submoduleId = null): RedirectResponse|JsonResponse|View</code> <a class="header-anchor" href="#show-id-submoduleid-null-redirectresponse-jsonresponse-view" aria-label="Permalink to &quot;`show($id, $submoduleId = null): RedirectResponse|JsonResponse|View`&quot;">​</a></h3><p>Fetches and displays a single resource. Redirects to <code>edit</code> if the module config does not define a show view.</p><h3 id="edit-id-jsonresponse-redirectresponse-view" tabindex="-1"><code>edit($id): JsonResponse|RedirectResponse|View</code> <a class="header-anchor" href="#edit-id-jsonresponse-redirectresponse-view" aria-label="Permalink to &quot;`edit($id): JsonResponse|RedirectResponse|View`&quot;">​</a></h3><p>Shows the edit form for a resource. Loads the form schema, relationships, and current field values. Redirects to index if the <code>edit</code> option is disabled.</p><h3 id="update-id-submoduleid-null-jsonresponse-redirectresponse" tabindex="-1"><code>update($id, $submoduleId = null): JsonResponse|RedirectResponse</code> <a class="header-anchor" href="#update-id-submoduleid-null-jsonresponse-redirectresponse" aria-label="Permalink to &quot;`update($id, $submoduleId = null): JsonResponse|RedirectResponse`&quot;">​</a></h3><p>Validates then calls <code>$repository-&gt;update()</code>. On success:</p><ul><li>Logs activity (<code>updated</code>).</li><li>Respects <code>cmsSaveType</code> for redirect target.</li></ul><h3 id="destroy-id-submoduleid-null-jsonresponse" tabindex="-1"><code>destroy($id, $submoduleId = null): JsonResponse</code> <a class="header-anchor" href="#destroy-id-submoduleid-null-jsonresponse" aria-label="Permalink to &quot;`destroy($id, $submoduleId = null): JsonResponse`&quot;">​</a></h3><p>Soft-deletes the resource via <code>$repository-&gt;delete()</code>. Returns a JSON success/error response.</p><h3 id="forcedelete-jsonresponse" tabindex="-1"><code>forceDelete(): JsonResponse</code> <a class="header-anchor" href="#forcedelete-jsonresponse" aria-label="Permalink to &quot;`forceDelete(): JsonResponse`&quot;">​</a></h3><p>Permanently deletes a soft-deleted resource. Requires the <code>forceDelete</code> index option to be enabled.</p><h3 id="restore-jsonresponse" tabindex="-1"><code>restore(): JsonResponse</code> <a class="header-anchor" href="#restore-jsonresponse" aria-label="Permalink to &quot;`restore(): JsonResponse`&quot;">​</a></h3><p>Restores a soft-deleted resource. Requires the <code>restore</code> index option to be enabled.</p><h3 id="duplicate-id-submoduleid-null-jsonresponse" tabindex="-1"><code>duplicate($id, $submoduleId = null): JsonResponse</code> <a class="header-anchor" href="#duplicate-id-submoduleid-null-jsonresponse" aria-label="Permalink to &quot;`duplicate($id, $submoduleId = null): JsonResponse`&quot;">​</a></h3><p>Duplicates the resource by cloning it and its relationships. Logs a <code>duplicated</code> activity event.</p><h2 id="bulk-actions" tabindex="-1">Bulk Actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk Actions&quot;">​</a></h2><h3 id="bulkdelete-jsonresponse" tabindex="-1"><code>bulkDelete(): JsonResponse</code> <a class="header-anchor" href="#bulkdelete-jsonresponse" aria-label="Permalink to &quot;`bulkDelete(): JsonResponse`&quot;">​</a></h3><p>Soft-deletes multiple resources by IDs.</p><h3 id="bulkforcedelete-jsonresponse" tabindex="-1"><code>bulkForceDelete(): JsonResponse</code> <a class="header-anchor" href="#bulkforcedelete-jsonresponse" aria-label="Permalink to &quot;`bulkForceDelete(): JsonResponse`&quot;">​</a></h3><p>Permanently deletes multiple resources by IDs.</p><h3 id="bulkrestore-jsonresponse" tabindex="-1"><code>bulkRestore(): JsonResponse</code> <a class="header-anchor" href="#bulkrestore-jsonresponse" aria-label="Permalink to &quot;`bulkRestore(): JsonResponse`&quot;">​</a></h3><p>Restores multiple soft-deleted resources by IDs.</p><h3 id="reorder-jsonresponse" tabindex="-1"><code>reorder(): JsonResponse</code> <a class="header-anchor" href="#reorder-jsonresponse" aria-label="Permalink to &quot;`reorder(): JsonResponse`&quot;">​</a></h3><p>Updates the sort position of multiple resources given an ordered array of IDs.</p><h2 id="save-type-behaviour" tabindex="-1">Save Type Behaviour <a class="header-anchor" href="#save-type-behaviour" aria-label="Permalink to &quot;Save Type Behaviour&quot;">​</a></h2><p>The frontend sends a <code>cmsSaveType</code> value with every save request to control where the user is redirected after the operation:</p><table><thead><tr><th><code>cmsSaveType</code></th><th>Redirect target</th></tr></thead><tbody><tr><td><code>save-close</code></td><td>Index listing</td></tr><tr><td><code>save-new</code></td><td>Create form</td></tr><tr><td>(default)</td><td>Edit form for the saved record</td></tr></tbody></table><h2 id="translation-fallback-chain" tabindex="-1">Translation Fallback Chain <a class="header-anchor" href="#translation-fallback-chain" aria-label="Permalink to &quot;Translation Fallback Chain&quot;">​</a></h2><p>User-facing messages (created, updated, deleted, etc.) are resolved in this order:</p><ol><li><code>{module}::{routeName}.{action}</code> translation key.</li><li><code>{module}::generic.{action}</code> translation key.</li><li>Modularous default message.</li></ol><h2 id="view-rendering" tabindex="-1">View Rendering <a class="header-anchor" href="#view-rendering" aria-label="Permalink to &quot;View Rendering&quot;">​</a></h2><p>When the <code>ManageInertia</code> trait is active (detected from module config), responses are rendered via Inertia instead of Blade. The view prefix <code>{module}::{route}</code> is used for both.</p>',48),d=[a];function n(i,l,c,p,h,u){return s(),o("div",null,d)}const f=e(r,[["render",n]]);export{m as __pageData,f as default};
